 = 0.9),","      hjust = -0.1,","      size = 2.5","    ) +","    scale_fill_discrete_qualitative(palette = \"Harmonic\") +","    scale_y_continuous(","      labels = scales::percent_format(accuracy = 1),","      breaks = seq(0, 1, 0.4),","      expand = expansion(mult = c(0, 0.1))","    ) +","    coord_cartesian(ylim = c(0, 5)) + ","    labs(","      title = paste0(","        \"不同光老化皮损类型在男女四个部位的发生率 (\",","        score_name, \")\"","      ),","      x = \"光老化类型\",","      y = \"发生率\"","    ) +","    coord_flip() +","    facet_grid(. ~ Position) +","    theme_classic(base_size = 12) +","    theme(","      legend.position = \"top\",","      axis.line.y = element_blank(),","      axis.ticks.y = element_blank(),","      strip.background = element_blank()","    )","  ","  return(g)","}","","plot_score_sex_position_lesion(data = dat_final, score_col = score1)"],colorizedLines:null,stylingDirectives:$R[351]={format:"compact",lineOffsets:$R[352]=[0,2,4,6,8,13,13,15,17,19,21,23,30,30,30,35,40,40,46,51,53,60,65,65,67,68,79,80,86,86,94,99,103,106,107,113,113,120,125,131,132,137,137,139,142,146,146,151,156,157,158,162,166,166,171,173,175,177,177,177,179,179,179,185],startsUtf16:$R[353]=[0,0,0,0,0,0,0,0,0,31,34,43,49,2,2,2,2,2,2,2,2,2,2,2,13,16,21,31,36,44,2,28,31,36,37,13,18,28,36,37,6,8,17,31,37,39,6,14,16,16,21,6,7,11,15,17,19,21,25,26,11,18,21,21,26,2,4,4,8,10,12,19,29,38,40,42,47,52,54,4,13,22,39,45,47,53,10,16,18,24,34,39,48,50,6,15,32,38,40,6,12,14,15,6,11,13,6,36,44,46,46,55,58,6,13,15,21,38,47,49,6,13,19,22,25,6,13,25,30,34,37,6,20,25,29,32,36,6,12,8,8,31,8,20,20,22,6,8,10,10,16,6,8,10,10,14,6,17,15,17,19,29,18,28,30,34,6,22,24,24,28,6,18,6,19,6,23,2,9,31,36,38,49,59,61],endsUtf16:$R[354]=[12,1,30,1,69,1,94,1,30,33,42,47,58,68,3,55,3,41,3,49,3,59,3,12,15,21,23,36,38,53,27,30,35,37,38,16,26,34,37,38,7,9,26,36,38,43,13,15,22,17,22,7,8,14,16,18,20,23,26,27,17,20,27,22,27,3,6,29,9,11,19,21,35,39,41,45,51,53,57,5,21,23,44,46,50,54,15,17,24,26,37,47,49,51,14,16,37,39,43,11,1